  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST1',
      status: 'issued',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-002',
      customerId: 'CUST2',
      status: 'issued',
      dueDate: '2026-10-15',
